106	function getHttpStatus(error: unknown): number | undefined {
107		if (isHevyHttpError(error)) {
108			return error.status;
109		}
110		if (!error || typeof error !== "object" || !("response" in error)) {
111			return undefined;
112		}
113	
114		const response = error.response;
115		if (!response || typeof response !== "object" || !("status" in response)) {
116			return undefined;
117		}
118	
119		return typeof response.status === "number" &&
120			Number.isInteger(response.status) &&
121			response.status >= 100 &&
122			response.status <= 599
123			? response.status
124			: undefined;
125	}
