130			return `HTTP ${status}`;
131		}
132	
133		if (!error || typeof error !== "object" || !("code" in error)) {
134			return undefined;
135		}
136	
137		const code = error.code;
138		return typeof code === "string" && SAFE_NETWORK_ERROR_CODES.has(code)
139			? code
140			: undefined;
