 19	export async function runCli(options: RunCliOptions): Promise<number> {
 20		const streams = options.streams ?? {
 21			stdout: (text) => process.stdout.write(text),
 22			stderr: (text) => process.stderr.write(text),
 23		};
 24		const state: { result?: unknown; error?: unknown } = {};
 25		const stricliProcess = {
 26			stdout: { write: streams.stdout },
 27			stderr: { write: streams.stderr },
 28			exitCode: undefined as number | undefined,
 29		};
 30		const context = {
 31			process: stricliProcess,
 32			state,
 33			now: options.now ?? (() => new Date()),
 34			readDataSource: options.readDataSource ?? readDataSource,
 35			client: undefined as HevyClient | undefined,
 36			operations: undefined as HevyOperations | undefined,
 37		};
 38		const metaCommand = options.argv.some((value) =>
 39			["--help", "-h", "--version", "-v"].includes(value),
 40		);
 41		try {
 42			if (!metaCommand) {
 43				const key = getApiKey(options.env ?? globalThis.process.env);
 44				const createdClient = (
 45					options.clientFactory ?? ((apiKey) => createHevyClient({ apiKey }))
 46				)(key);
 47				const client = options.execution
 48					? bindClientExecution(createdClient, options.execution)
 49					: createdClient;
 50				context.client = client;
 51				context.operations = createOperations(client);
 52			}
 53			const exitCode = await runRoutes(options.argv, context);
 54			if (state.error !== undefined) throw state.error;
 55			if (exitCode !== 0) return EXIT.usage;
 56			if (state.result !== undefined) {
 57				const json = options.argv.includes("--json");
 58				writeResult(state.result, json, streams);
 59			}
 60			return 0;
 61		} catch (error) {
 62			const failure = diagnostic(error);
 63			if (options.argv.includes("--json")) {
 64				streams.stderr(`${JSON.stringify(failure)}\n`);
 65			} else {
 66				streams.stderr(`${failure.message}\n`);
 67			}
 68			return failure.code;
 69		}
 70	}
