 92	function toArgs(
 93		command: string,
 94		subcommand: string | undefined,
 95		flags: object,
 96		positionals: string[],
 97	): CliArgs {
 98		const options: Record<string, string | boolean> = {};
 99		for (const [name, value] of Object.entries(flags)) {
100			if (typeof value === "string" || typeof value === "boolean")
101				options[name] = value;
102		}
