106	async function invoke(
107		context: CliRuntimeContext,
108		command: string,
109		subcommand: string | undefined,
110		flags: CliFlags,
111		positionals: string[],
112	): Promise<void> {
113		try {
114			if (!context.client) {
115				throw new Error("Hevy API client is not configured");
116			}
117			context.state.result = await execute(
118				toArgs(command, subcommand, flags, positionals),
119				context.client,
120				context.now,
121				context.readDataSource,
122				context.operations,
123			);
124		} catch (error) {
125			context.state.error = error;
126		}
127	}
