 17	/** Project either structured errors or client observations into stable OTel keys. */
 18	export function projectExecutionAttributes(
 19		execution: ExecutionAttributeSource | undefined,
 20		namespace: ExecutionTelemetryNamespace = "span",
 21	): Record<string, string | boolean> {
 22		if (!execution) return {};
 23		const prefix = namespace === "span" ? "hevy.api." : "";
 24		const operationSafety =
 25			execution.operation_safety ?? execution.operationSafety;
 26		const commitState = execution.commit_state ?? execution.commitState;
 27		const safeToRetry = execution.safe_to_retry ?? execution.safeToRetry;
 28		return {
 29			...(execution.outcome ? { [`${prefix}outcome`]: execution.outcome } : {}),
 30			...(execution.phase ? { [`${prefix}phase`]: execution.phase } : {}),
 31			...(operationSafety
 32				? { [`${prefix}operation_safety`]: operationSafety }
 33				: {}),
 34			...(commitState ? { [`${prefix}commit_state`]: commitState } : {}),
 35			...(safeToRetry !== undefined
 36				? { [`${prefix}safe_to_retry`]: safeToRetry }
 37				: {}),
 38		};
 39	}
