  2	 * Preprocessor to handle MCP clients that send JSON-stringified arrays
  3	 * instead of native arrays for complex parameters.
  4	 *
  5	 * This is used with Zod's z.preprocess to handle cases where MCP clients
  6	 * serialize complex nested structures as JSON strings.
  7	 *
  8	 * @param val - The value to potentially parse
  9	 * @returns The parsed array if val is a valid JSON string, otherwise returns val unchanged
 10	 */
 11	export function parseJsonArray(val: unknown): unknown {
 12		// Handle case where MCP client sends JSON string instead of array
 13		if (typeof val === "string") {
 14			try {
 15				return JSON.parse(val);
 16			} catch {
 17				// Let Zod validation handle the error
 18				return val;
 19			}
 20		}
 21		return val;
 22	}
  1	import { z } from "zod";
  2	
  3	type JsonSchema = Record<string, unknown>;
  4	
  5	function isRecord(value: unknown): value is JsonSchema {
  6		return value !== null && typeof value === "object" && !Array.isArray(value);
  7	}
  8	
  9	function isNullSchema(value: unknown): value is JsonSchema {
 10		return (
 11			isRecord(value) && value.type === "null" && Object.keys(value).length === 1
 12		);
 13	}
 14	
 15	function compactNullableSchema(value: unknown): unknown {
 16		if (Array.isArray(value)) {
 17			return value.map(compactNullableSchema);
 18		}
 19		if (!isRecord(value)) {
 20			return value;
 21		}
 22	
 23		const anyOf = value.anyOf;
 24		if (Array.isArray(anyOf) && anyOf.length === 2) {
 25			const nullableBranch = anyOf.find(isNullSchema);
 26			const valueBranch = anyOf.find((branch) => !isNullSchema(branch));
 27			if (
 28				nullableBranch !== undefined &&
 29				isRecord(valueBranch) &&
 30				typeof valueBranch.type === "string"
 31			) {
 32				const { anyOf: _anyOf, ...metadata } = value;
 33				return compactNullableSchema({
 34					...valueBranch,
 35					...metadata,
 36					type: [valueBranch.type, "null"],
 37				});
 38			}
 39		}
 40	
 41		return Object.fromEntries(
 42			Object.entries(value).map(([key, nested]) => [
 43				key,
 44				compactNullableSchema(nested),
 45			]),
 46		);
 47	}
 48	
 49	function omitOutputObjectRestrictions(value: unknown): unknown {
 50		if (Array.isArray(value)) {
 51			return value.map(omitOutputObjectRestrictions);
 52		}
 53		if (!isRecord(value)) {
 54			return value;
 55		}
 56		return Object.fromEntries(
 57			Object.entries(value)
 58				.filter(
 59					([key, nested]) => key !== "additionalProperties" || nested !== false,
 60				)
 61				.map(([key, nested]) => [key, omitOutputObjectRestrictions(nested)]),
 62		);
 63	}
 64	
 65	function convertSchema(
 66		schema: z.ZodTypeAny,
 67		io: "input" | "output",
 68	): JsonSchema {
 69		const converted = z.toJSONSchema(schema, {
 70			target: "draft-2020-12",
 71			io,
 72		});
 73		if (!isRecord(converted)) {
 74			throw new Error("Zod emitted a non-object root schema");
 75		}
 76		const compacted = compactNullableSchema(converted);
 77		if (!isRecord(compacted)) {
 78			throw new Error("Nullable schema compaction changed the root schema");
 79		}
 80		const output =
 81			io === "output" ? omitOutputObjectRestrictions(compacted) : compacted;
 82		if (!isRecord(output)) {
 83			throw new Error("Output schema compaction changed the root schema");
 84		}
 85		delete output.$schema;
 86		return output;
 87	}
 88	
 89	/**
 90	 * Keep Zod validation while advertising a compact JSON Schema.
 91	 *
 92	 * Zod emits nullable values as `anyOf`; draft 2020-12 also permits a type
 93	 * array. The MCP wire envelope does not need a repeated `$schema` marker, and
 94	 * structured output is validated by the original Zod schema before sending.
 95	 */
 96	export function compactJsonSchema<TSchema extends z.ZodTypeAny>(
 97		schema: TSchema,
 98	): TSchema {
 99		let inputSchema: JsonSchema | undefined;
100		let outputSchema: JsonSchema | undefined;
101		Object.defineProperty(schema["~standard"], "jsonSchema", {
102			configurable: true,
103			value: {
104				input: () => {
105					inputSchema ??= convertSchema(schema, "input");
106					return inputSchema;
107				},
108				output: () => {
109					outputSchema ??= convertSchema(schema, "output");
110					return outputSchema;
111				},
112			},
113			writable: true,
114		});
115		return schema;
116	}
