 11	
 12	/**
 13	 * Assert that the Hevy API client is initialized before running a tool.
 14	 */
 15	export function requireClient<TClient>(client: TClient | null): TClient {
 16		if (!client) {
 17			throw new Error(HEVY_CLIENT_NOT_INITIALIZED_ERROR);
 18		}
 19	
 20		return client;
 21	}
