 23	/**
 24	 * Infer TypeScript types from Zod schema objects
 25	 *
 26	 * @example
 27	 * ```typescript
 28	 * const schema = {
 29	 *   page: z.number(),
 30	 *   pageSize: z.number(),
 31	 * } as const;
 32	 *
 33	 * type Params = InferToolParams<typeof schema>; // { page: number; pageSize: number }
 34	 * ```
 35	 */
 36	export type InferToolParams<T extends Record<string, z.ZodTypeAny>> = z.infer<
 37		z.ZodObject<T>
 38	>;
 39	
 40	/**
 41	 * Create a type-safe tool handler that validates and narrows args to inferred types
 42	 *
 43	 * This function wraps a handler with automatic Zod validation, ensuring runtime
 44	 * type safety while maintaining compile-time type inference.
 45	 *
 46	 * @param schema - Zod schema object (e.g., { page: z.number(), ... })
 47	 * @param handler - Handler function that receives validated, typed parameters
 48	 * @returns A handler function that accepts Record<string, unknown> and validates it
 49	 *
 50	 * @example
 51	 * ```typescript
 52	 * const schema = {
 53	 *   page: z.coerce.number().int().gte(1).default(1),
 54	 *   pageSize: z.coerce.number().int().gte(1).lte(10).default(5),
 55	 * } as const;
 56	 *
 57	 * const handler = createTypedToolHandler(schema, async (args) => {
 58	 *   // args is fully typed as { page: number; pageSize: number }
 59	 *   const { page, pageSize } = args;
 60	 *   // ...
 61	 * });
 62	 * ```
 63	 */
 64	export function createTypedToolHandler<T extends Record<string, z.ZodTypeAny>>(
 65		schema: T,
 66		handler: (
 67			args: InferToolParams<T>,
 68			context?: ToolExecutionContext,
 69		) => Promise<McpToolResponse>,
 70	): (
 71		args: Record<string, unknown>,
 72		context?: ToolExecutionContext,
 73	) => Promise<McpToolResponse> {
 74		const zodSchema = z.strictObject(schema);
 75		return async (
 76			args: Record<string, unknown>,
 77			context?: ToolExecutionContext,
 78		) => {
 79			const validated = zodSchema.parse(args);
 80			return handler(validated, context);
 81		};
 82	}

