 19	type RoutineRepRange = { start?: number; end?: number } | null;
 20	
 21	function buildRepRange(
 22		repRange: { start?: number | null; end?: number | null } | null | undefined,
 23	): RoutineRepRange {
 24		if (!repRange) {
 25			return null;
 26		}
 27	
 28		const start = repRange.start ?? undefined;
 29		const end = repRange.end ?? undefined;
 30		if (start === undefined && end === undefined) {
 31			return null;
 32		}
 33	
 34		return { start, end };
 35	}
