 70					? set.reps
 71					: getFixedRepsFromRepRange(repRange);
 72			const common = {
 73				weight_kg: set.weight_kg ?? null,
 74				reps: reps ?? null,
 75				distance_meters: set.distance_meters ?? null,
 76				duration_seconds: set.duration_seconds ?? null,
 77				custom_metric: set.custom_metric ?? null,
 78			};
 79	
 80			if (mode === "create") {
 81				return {
 82					...common,
 83					type: set.type,
 84					rep_range: repRange,
 85				};
 86			}
 87			return {
 88				...common,
 89				type: set.type,
