247	/** Omit nullish measurement values because the API rejects explicit nulls. */
248	export function buildMeasurementPayload(
249		fields: Partial<MeasurementFields>,
250	): MeasurementPayload {
251		const payload: MeasurementPayload = {};
252		for (const key of measurementKeys) {
