261	export function mergeMeasurementPayload(
262		existing: BodyMeasurement,
263		changes: MeasurementFields,
264	): { payload: MeasurementPayload; measurement: BodyMeasurement } {
265		const payload: MeasurementPayload = {};
266		const measurement = { ...existing };
267	
268		for (const key of measurementKeys) {
269			const changed = changes[key];
270			if (changed !== undefined) {
271				if (changed !== null) {
272					measurement[key] = changed;
273					payload[key] = changed;
274				}
275				continue;
276			}
277			const existingValue = existing[key];
278			if (existingValue != null) payload[key] = existingValue;
279		}
280	
281		return { payload, measurement };
282	}

