   200	function defaultSleep(
   201		milliseconds: number,
   202		signal?: AbortSignal,
   203	): Promise<void> {
   204		if (signal?.aborted) {
   205			return Promise.reject(
   206				signal.reason ?? new DOMException("Operation canceled", "AbortError"),
   207			);
   208		}
   209		return new Promise((resolve, reject) => {
   210			let settled = false;
   211			let timer: ReturnType<typeof setTimeout> | undefined;
   212			const cleanup = () => {
   213				if (timer !== undefined) clearTimeout(timer);
   214				signal?.removeEventListener("abort", onAbort);
   215			};
   216			const resolveSleep = () => {
   217				if (settled) return;
   218				settled = true;
   219				cleanup();
   220				resolve();
   221			};
   222			const rejectSleep = (reason: unknown) => {
   223				if (settled) return;
   224				settled = true;
   225				cleanup();
   226				reject(reason);
   227			};
   228			const onAbort = () =>
   229				rejectSleep(
   230					signal?.reason ?? new DOMException("Operation canceled", "AbortError"),
   231				);
   232			timer = setTimeout(resolveSleep, Math.max(0, milliseconds));
   233			signal?.addEventListener("abort", onAbort, { once: true });
   234			if (signal?.aborted) onAbort();
   235		});
   236	}
