   238	function withTimeout<T>(
   239		operation: Promise<T>,
   240		timeoutMs: number,
   241		onTimeout: () => void,
   242		signal?: AbortSignal,
   243	): Promise<T> {
   244		const promise = new Promise<T>((resolve, reject) => {
   245			let settled = false;
   246			const onAbort = () => {
   247				if (settled) return;
   248				settled = true;
   249				if (timer !== undefined) clearTimeout(timer);
   250				signal?.removeEventListener("abort", onAbort);
   251				reject(
   252					signal?.reason ?? new DOMException("Operation canceled", "AbortError"),
   253				);
   254			};
   255			const timer = Number.isFinite(timeoutMs)
   256				? setTimeout(
   257						() => {
   258							if (settled) return;
   259							settled = true;
   260							signal?.removeEventListener("abort", onAbort);
   261							onTimeout();
   262							reject(new DOMException("Operation timed out", "TimeoutError"));
   263						},
   264						Math.max(0, timeoutMs),
   265					)
   266				: undefined;
   267			operation.then(
   268				(value) => {
   269					if (settled) return;
   270					settled = true;
   271					if (timer !== undefined) clearTimeout(timer);
   272					signal?.removeEventListener("abort", onAbort);
   273					resolve(value);
   274				},
   275				(error: unknown) => {
   276					if (settled) return;
   277					settled = true;
   278					if (timer !== undefined) clearTimeout(timer);
   279					signal?.removeEventListener("abort", onAbort);
   280					reject(error);
   281				},
   282			);
   283			if (signal?.aborted) onAbort();
   284			else signal?.addEventListener("abort", onAbort, { once: true });
   285		});
   286		return promise;
   287	}
