   396	function parseRetryAfterMs(value: string | null): number | undefined {
   397		if (!value) return undefined;
   398		const seconds = Number(value);
   399		if (Number.isFinite(seconds) && seconds >= 0) {
   400			return Math.round(seconds * 1_000);
   401		}
