 68	export function installGracefulShutdown({
 69		target,
 70		process: processLike = process,
 71		logError = console.error,
 72		flush = flushStdout,
 73		forcedExitTimeoutMs = FORCED_EXIT_TIMEOUT_MS,
 74		scheduleForcedExit = setTimeout,
 75		cancel,
 76		onComplete,
 77	}: GracefulShutdownOptions): GracefulShutdownController {
 78		let listenersInstalled = true;
 79		let shutdownSettled = false;
 80		let shutdownPromise: Promise<void> | undefined;
 81		let completionReported = false;
 82	
 83		const reportCompletion = (succeeded: boolean): Promise<void> | undefined => {
 84			if (completionReported) return undefined;
 85			completionReported = true;
 86			try {
 87				const completion = onComplete?.(succeeded);
 88				return completion
 89					? Promise.resolve(completion).catch(() => {
 90							logError("Graceful shutdown completion observer failed");
 91						})
 92					: undefined;
 93			} catch {
 94				logError("Graceful shutdown completion observer failed");
 95				return undefined;
 96			}
 97		};
 98	
 99		const cleanup = () => {
100			if (!listenersInstalled || (shutdownPromise && !shutdownSettled)) {
101				return;
102			}
103	
104			listenersInstalled = false;
105			for (const signal of shutdownSignals) {
106				const listener = signalListeners.get(signal);
107				if (listener) {
108					processLike.removeListener(signal, listener);
109				}
110			}
111		};
112	
113		const handleSignal = (signal: ShutdownSignal) => {
114			if (shutdownPromise) {
115				return;
116			}
117	
118			if (processLike.exitCode == null) {
119				processLike.exitCode = 0;
120			}
121			cancel?.abort(
122				new DOMException(`Shutdown requested by ${signal}`, "AbortError"),
123			);
124	
125			const forcedExitTimer = scheduleForcedExit(() => {
126				void reportCompletion(false);
127				processLike.exit(shutdownSettled ? (processLike.exitCode ?? 0) : 1);
128			}, forcedExitTimeoutMs);
129			// This fallback must survive successful shutdown so it can terminate a
130			// process held open by unrelated handles, without keeping the process alive
131			// when the event loop drains normally.
132			forcedExitTimer.unref();
133	
134			shutdownPromise = (async () => {
135				logError(`Shutting down gracefully after ${signal}`);
136				let shutdownFailed = false;
137				let shutdownError: unknown;
138	
139				try {
140					await target.close();
141				} catch (error) {
142					shutdownFailed = true;
143					shutdownError = error;
144				}
145	
146				try {
147					await flush();
148				} catch (error) {
149					if (!shutdownFailed) {
150						shutdownError = error;
151					}
152					shutdownFailed = true;
153				}
154	
155				try {
156					if (shutdownFailed) {
157						const message =
158							shutdownError instanceof Error
159								? shutdownError.message
160								: "Unknown shutdown error";
161						logError(`Graceful shutdown failed: ${message}`);
162						processLike.exitCode = 1;
163						return;
164					}
165				} finally {
166					await reportCompletion(!shutdownFailed);
167					shutdownSettled = true;
168					cleanup();
169				}
170			})();
171		};
172	
173		const signalListeners = new Map<ShutdownSignal, () => void>(
174			shutdownSignals.map((signal) => [signal, () => handleSignal(signal)]),
175		);
176	
177		for (const signal of shutdownSignals) {
178			const listener = signalListeners.get(signal);
179			if (listener) {
180				processLike.on(signal, listener);
181			}
182		}
183	
184		return {
185			cleanup,
186			getShutdownPromise: () => shutdownPromise,
187		};
188	}
