 49	export function installProcessExceptionTracking(
 50		processLike: ProcessExceptionSource = process,
 51	): () => void {
 52		if (!telemetryEnabled) return () => {};
 53		const recordProcessException = (
 54			source: keyof typeof PROCESS_FAILURE_TAXONOMY,
 55			error: unknown,
 56		) => {
 57			try {
 58				tracer.startActiveSpan(
 59					`mcp.process.${source}`,
 60					{ attributes: { "mcp.span.category": "process" } },
 61					(span) => {
 62						try {
 63							captureFailure(error, {
 64								kind: "process",
 65								attributes: {
 66									"exception.source": source,
 67									"mcp.failure.phase": PROCESS_FAILURE_TAXONOMY[source],
 68									"error.type": "MCP_PROCESS_EXCEPTION",
 69									"error.category": "McpProcessFailure",
 70								},
 71								span,
 72							});
 73						} finally {
