    72			"mcp.tool.name": toolName,
    73			"error.type": errorType,
    74			"error.category": diagnostic.category,
    75			...(diagnostic.code ? { "error.code": diagnostic.code } : {}),
    76			...(diagnostic.status !== undefined
    77				? { "http.status_code": diagnostic.status }
    78				: {}),
    79			...(diagnostic.method ? { "http.method": diagnostic.method } : {}),
    80			...(diagnostic.endpoint
