   110	/**
   111	 * Create a standardized error response for MCP tools
   112	 *
   113	 * @param error - The error object or message
   114	 * @param context - Optional context information about where the error occurred
   115	 * @returns A formatted MCP tool response with error information
   116	 */
   117	export function createErrorResponse(
   118		error: unknown,
   119		context?: string,
   120	): McpToolResponse {
   121		const policy = resolveErrorPolicy(
   122			error,
   123			"The request failed unexpectedly. Please try again.",
   124			HEVY_CLIENT_NOT_INITIALIZED_ERROR,
   125		);
   126		const { diagnostic } = policy;
   127		const execution = createExecutionProjection(diagnostic);
   128		const axiosErrorContext: ErrorDebugContext["axios"] | null =
   129			diagnostic.status !== undefined ||
   130			diagnostic.method !== undefined ||
   131			diagnostic.endpoint !== undefined
   132				? {
   133						status: diagnostic.status,
   134						method: diagnostic.method,
   135						url: diagnostic.endpoint,
   136					}
   137				: null;
   138		const errorContext: ErrorDebugContext = {
   139			sourceContext: context,
   140			originalErrorMessage: `${diagnostic.category} occurred`,
   141			errorCode: diagnostic.code,
   142			errorType: policy.type,
   143			execution,
   144			axios: axiosErrorContext ?? undefined,
   145		};
   146		const contextPrefix = context ? `[${context}] ` : "";
   147		const formattedMessage = `${contextPrefix}Error: ${policy.message}`;
   148		console.error(
   149			JSON.stringify(
   150				createMcpToolFailureEvent(context || "unknown", policy.type, {
   151					...diagnostic,
   152					execution,
   153				}),
   154			),
   155		);
   156	
   157		return {
   158			content: [{ type: "text" as const, text: formattedMessage }],
   159			isError: true,
   160			errorContext,
   161			structuredContent: { error: execution },
   162			errorOutcome: execution,
   163		};
   164	}
