 33	function createCountingServer(server: McpServer) {
 34		let count = 0;
 35		const countingServer = new Proxy(server, {
 36			get(target, property, receiver) {
 37				if (property === "registerTool") {
 38					const registerTool = target.registerTool.bind(target);
 39					return (...args: unknown[]) => {
 40						const result = Reflect.apply(registerTool, target, args);
 41						count += 1;
 42						return result;
 43					};
 44				}
 45				return Reflect.get(target, property, receiver);
 46			},
 47		});
 48		return { server: countingServer, getCount: () => count };
 49	}
