 51	export function createHevyMcpServer(
 52		options: CreateHevyMcpServerOptions,
 53	): McpServer {
 54		const baseServer = new McpServer(
 55			{ name: SERVER_NAME, version: SERVER_VERSION },
 56			{ capabilities: { logging: {} }, instructions: SERVER_INSTRUCTIONS },
 57		);
 58		const server = options.decorateServer?.(baseServer) ?? baseServer;
 59		const mcpLogger = createMcpClientLogger(server);
 60		const client = options.createClient({ onLog: (event) => mcpLogger(event) });
 61		const runtime = createToolRuntime({
 62			client,
 63			catalog: createExerciseTemplateCatalog(client, options.cacheObserver),
 64			logger: mcpLogger,
 65			observer: options.observer,
 66			executionTimeoutMs: options.executionTimeoutMs,
 67			executionDeadline: options.executionDeadline,
 68			lifecycleSignal: options.lifecycleSignal,
 69		});
 70		const counting = createCountingServer(server);
 71		registerHevyTools(counting.server, runtime);
 72		options.onToolsRegistered?.(counting.getCount());
 73		registerWorkoutPrompts(server, options.observer);
 74		registerHevyResources(server, runtime);
 75		return server;
 76	}
