 15	function withPromptObservation<TArgs extends Record<string, unknown>>(
 16		name: string,
 17		observer: ToolObserver | undefined,
 18		handler: (args: TArgs) => Promise<PromptResult> | PromptResult,
 19	) {
 20		return async (args: TArgs): Promise<PromptResult> => {
 21			const startedAt = Date.now();
 22			let scope;
 23			try {
 24				scope = memoizeObservationScope(
 25					observer?.start({
 26						name,
 27						kind: "prompt",
 28						argumentKeys: Object.keys(args).filter(
 29							(key) => key === "routine_id",
 30						) as "routine_id"[],
 31						argumentPresence: args.routine_id ? { routine_id: true } : {},
 32						argumentKeyCountBucket: bucketCount(Object.keys(args).length),
 33					}),
 34				);
 35			} catch {
 36				scope = undefined;
 37			}
 38	
 39			try {
 40				const invoke = () => Promise.resolve(handler(args));
 41				const result = await (scope ? scope.run(invoke) : invoke());
 42				void scope?.finish({
 43					outcome: "success",
 44					durationMs: Date.now() - startedAt,
 45					result: {
 46						isError: false,
 47						hasStructuredContent: false,
 48						contentCountBucket: bucketCount(result.messages.length),
 49					},
 50				});
 51				return result;
 52			} catch (error) {
 53				const policy = resolveErrorPolicy(error, "MCP prompt failed");
 54				void scope?.finish({
 55					outcome: "thrown_error",
 56					durationMs: Date.now() - startedAt,
 57					errorType: policy.type,
 58					error: policy.diagnostic,
 59				});
 60				console.error("MCP prompt failure", policy.diagnostic);
 61				throw error;
 62			}
 63		};
 64	}
